  exists big' d' c', fmt_fp_up_inner sh BIG_FUEL a (big, z - 1, 0) = Some (big', d', c') /\
    W9 big' /\ 0 <= c' < NB /\ zlength big' = 128 /\ d' = a - 1 /\
