Definition UPI (z0 : Z) (s : list Z * Z * Z * Z) : Prop :=
  let '(big, a, z, e2) := s in
  W9 big /\ zlength big = 128 /\ 0 <= a < z /\ z <= z0 /\ a <= 122 /\ 122 - a + upm e2 <= 36 /\ 0 <= e2 <= 1024 /\
  znth big a <> 0 /\ zeros_below big a /\ zeros_from big z.

