(* [comment removed for export] *)
Definition DNI (s : list Z * Z * Z * Z) : Prop :=
  let '(big, a, z, e2) := s in
  W9 big /\ zlength big = 128 /\ 0 <= a < z /\ znth big a <> 0 /\ zeros_below big a /\
  z + dnm e2 <= 127 /\ -1102 <= e2 <= 0 /\ znth big 0 < 2^29.

