Lemma upd_nat_same : forall l i, upd_nat l i (nth i l 0) = l.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S80!1+1+2%i;R+aI!3+40!3'aU#2#1!4'aV+2#1#2,6#2!1,?+2!2,V02!1,aM#1!3,^?+2#5#4!3,^?+2#4#3!3,^?+2#6#5$l;R0!5'aT+2$l;R01$i0;R+aI-aIRN$n;R+aI!3+40!3'aU2#1!4'aV+2#12,62#12vd3!3+40!3'aU2,^F!4'aV+2,^F2,62$n;R+aI!1$i;R+aIvd3!3+40!3'aU24!4'aV+242,62#1$h;R+2$l;R0$IH;R1$i0;R+aI-aIRN$n;R+aI!3+40!3'aU5#1!4'aV+2#15,65#12vd!2,V06!3+40!3'aU6,^F!4'aV+2,^F6,66$n;R+aI!1$i;R+aIvd!6'^30#5$l;R0!3+40!3,^?+2#7#1!3,^?+2#7#6!2,V07!3'aU#5#1!4'aV+2#1#5,6!1#4#1!3+40!3'aU74!4'aV+247,67#1#1").
